/**
 * ============================================================================
 *  EXPERT PANEL — TO'LOV TIZIMI (HAMMASI BITTA FAYLDA)
 * ============================================================================
 *
 *  Bu bitta fayl butun saytni (index.html) VA barcha backend logikasini
 *  (Firebase bilan ishlash, Telegram bot bilan avtomatik moslashtirish,
 *  admin panel API'lari) o'z ichiga oladi.
 *
 *  ISHGA TUSHIRISH:
 *    1) npm install express firebase-admin
 *    2) Quyidagi "SOZLAMALAR" bo'limidagi environment variable'larni
 *       serveringizda (yoki .env faylda) belgilang.
 *    3) node server.js
 *
 *  environment variable'lar (majburiy):
 *    FIREBASE_SERVICE_ACCOUNT_KEY  — Firebase Console → Project settings →
 *      Service accounts → "Generate new private key" orqali olingan JSON
 *      faylning TO'LIQ mazmuni (bitta qator matn sifatida).
 *    FIREBASE_DATABASE_URL         — masalan https://expertpaneluz-default-rtdb.firebaseio.com
 *    ADMIN_SECRET                  — admin panel uchun kuchli parol
 *    BOT_TOKEN                     — "kartaga pul tushdi" xabarini yuboradigan bot tokeni
 *    ADMIN_CHAT_ID                 — mos kelmagan to'lov haqida sizga xabar keladigan chat ID
 *
 *  environment variable'lar (ixtiyoriy):
 *    CARD_NUMBER, CARD_HOLDER      — ko'rsatiladigan karta ma'lumotlari
 *    PORT                          — server porti (default: 3000)
 *
 *  Telegram webhookni ulash (deploy qilingandan keyin):
 *    curl "https://api.telegram.org/bot<BOT_TOKEN>/setWebhook?url=https://SIZNING-DOMEN/api/telegram-webhook"
 *
 *  MUHIM: bu server FAQAT backend logikani bitta faylga jamlaydi — Firebase
 *  loyihangiz (Authentication + Realtime Database) baribir kerak, chunki
 *  foydalanuvchilar, balans va to'lov so'rovlari o'sha yerda saqlanadi.
 *  Realtime Database "Rules" bo'limiga oldin berilgan database.rules.json
 *  qoidalarini albatta qo'ying — aks holda balansni brauzerdan
 *  to'g'ridan-to'g'ri o'zgartirish mumkinligicha qolaveradi.
 * ============================================================================
 */

const express = require("express");
const admin = require("firebase-admin");

// ---------------------------------------------------------------------------
// 1) FIREBASE ADMIN SDK ULANISHI
// ---------------------------------------------------------------------------
function getServiceAccount() {
    const raw = process.env.FIREBASE_SERVICE_ACCOUNT_KEY;
    if (!raw) {
        throw new Error(
            "FIREBASE_SERVICE_ACCOUNT_KEY environment o'zgaruvchisi topilmadi. " +
                "Firebase Console → Project settings → Service accounts orqali oling."
        );
    }
    try {
        return JSON.parse(raw);
    } catch (e) {
        throw new Error("FIREBASE_SERVICE_ACCOUNT_KEY noto'g'ri JSON formatida");
    }
}

admin.initializeApp({
    credential: admin.credential.cert(getServiceAccount()),
    databaseURL: process.env.FIREBASE_DATABASE_URL,
});
const db = admin.database();

// ---------------------------------------------------------------------------
// 2) SOZLAMALAR
// ---------------------------------------------------------------------------
const ADMIN_SECRET = process.env.ADMIN_SECRET || "";
const BOT_TOKEN = process.env.BOT_TOKEN || "";
const ADMIN_CHAT_ID = process.env.ADMIN_CHAT_ID || "";
const CARD_NUMBER = process.env.CARD_NUMBER || "9860196617132333";
const CARD_HOLDER = process.env.CARD_HOLDER || "Z. A.";
const PORT = process.env.PORT || 3000;

const TOPUP_TTL_MS = 2 * 60 * 1000; // 2 daqiqa
const MIN_TOPUP = 1000;

// ---------------------------------------------------------------------------
// 3) YORDAMCHI FUNKSIYALAR
// ---------------------------------------------------------------------------
function checkAdminSecret(req, res) {
    if (!ADMIN_SECRET) {
        res.status(500).json({ success: false, error: "Serverda ADMIN_SECRET sozlanmagan" });
        return false;
    }
    if (!req.body || req.body.adminSecret !== ADMIN_SECRET) {
        res.status(403).json({ success: false, error: "Ruxsat yo'q (parol noto'g'ri)" });
        return false;
    }
    return true;
}

async function sendTelegramMessage(text) {
    if (!BOT_TOKEN || !ADMIN_CHAT_ID) {
        console.warn("Telegram bot sozlanmagan — xabar yuborilmadi:", text);
        return;
    }
    try {
        await fetch(`https://api.telegram.org/bot${BOT_TOKEN}/sendMessage`, {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ chat_id: ADMIN_CHAT_ID, text, parse_mode: "HTML" }),
        });
    } catch (e) {
        console.error("Telegramga xabar yuborishda xatolik:", e);
    }
}

