const app = express();
app.use(express.json());

app.get("/", (req, res) => {
    res.set("Content-Type", "text/html; charset=utf-8");
    res.send(INDEX_HTML);
});

// ================= 5.1) FOYDALANUVCHI: TO'LDIRISH SO'ROVI YARATISH =================
app.post("/api/create-topup", async (req, res) => {
    try {
        const { idToken, amount } = req.body || {};
        if (!idToken) {
            return res.status(401).json({ success: false, error: "Avtorizatsiya talab qilinadi" });
        }

        const decoded = await admin.auth().verifyIdToken(idToken);
        const uid = decoded.uid;
        const email = decoded.email || "";

        const amt = Math.floor(Number(amount));
        if (!amt || amt < MIN_TOPUP) {
            return res.json({ success: false, error: `Minimal miqdor ${MIN_TOPUP} so'm` });
        }

        const now = Date.now();

        // 1) Shu foydalanuvchining allaqachon FAOL so'rovi bormi?
        const mineSnap = await db.ref("topupRequests").orderByChild("uid").equalTo(uid).once("value");
        let ownActive = null;
        mineSnap.forEach((child) => {
            const v = child.val();
            if (v.status === "pending" && v.expiresAt > now) {
                ownActive = { key: child.key, ...v };
            }
        });
        if (ownActive) {
            return res.json({
                success: true,
                requestId: ownActive.key,
                uniqueAmount: ownActive.uniqueAmount,
                expiresAt: ownActive.expiresAt,
                cardNumber: CARD_NUMBER,
                cardHolder: CARD_HOLDER,
            });
        }

        // 2) Shu BAZA summaga hozir boshqa kimdir navbatda turgan bo'lsa — bloklaymiz.
        const sameAmountSnap = await db.ref("topupRequests").orderByChild("baseAmount").equalTo(amt).once("value");
        let blocking = null;
        sameAmountSnap.forEach((child) => {
            const v = child.val();
            if (v.status === "pending" && v.expiresAt > now) blocking = v;
        });
        if (blocking) {
            const waitSec = Math.max(1, Math.ceil((blocking.expiresAt - now) / 1000));
            return res.json({
                success: false,
                error:
                    `Hozir shu summada (${amt.toLocaleString("uz-UZ")} so'm) boshqa foydalanuvchi ` +
                    `to'lov qilyapti. ${waitSec} soniyadan so'ng qayta urinib ko'ring yoki boshqa summa kiriting.`,
            });
        }

        // 3) Unikal (aniq) summani generatsiya qilish (kolliziyasiz).
        const activeSnap = await db.ref("topupRequests").orderByChild("status").equalTo("pending").once("value");
        const activeUniqueAmounts = new Set();
        activeSnap.forEach((child) => {
            const v = child.val();
            if (v.expiresAt > now) activeUniqueAmounts.add(v.uniqueAmount);
        });

        let uniqueAmount;
        let tries = 0;
        do {
            uniqueAmount = amt + (Math.floor(Math.random() * 900) + 100);
            tries++;
        } while (activeUniqueAmounts.has(uniqueAmount) && tries < 50);

        const expiresAt = now + TOPUP_TTL_MS;
        const newReqRef = db.ref("topupRequests").push();
        await newReqRef.set({
            uid,
            email,
            baseAmount: amt,
            uniqueAmount,
            status: "pending",
            createdAt: now,
            expiresAt,
        });

        return res.json({
            success: true,
            requestId: newReqRef.key,
            uniqueAmount,
            expiresAt,
            cardNumber: CARD_NUMBER,
            cardHolder: CARD_HOLDER,
        });
    } catch (e) {
        console.error("create-topup xatoligi:", e);
        return res.status(500).json({ success: false, error: "Server xatoligi" });
    }
});

// ================= 5.2) FOYDALANUVCHI: TAYMER TUGAGANDA O'ZINI "EXPIRED" QILISH =================
app.post("/api/expire-topup", async (req, res) => {
    try {
        const { idToken, requestId } = req.body || {};
        if (!idToken || !requestId) {
            return res.status(400).json({ success: false, error: "Ma'lumot yetarli emas" });
        }
        const decoded = await admin.auth().verifyIdToken(idToken);
        const uid = decoded.uid;

        const reqRef = db.ref(`topupRequests/${requestId}`);
        const snap = await reqRef.once("value");
        if (!snap.exists()) return res.json({ success: false, error: "So'rov topilmadi" });
        const v = snap.val();
        if (v.uid !== uid) return res.status(403).json({ success: false, error: "Bu sizning so'rovingiz emas" });

        if (v.status === "pending" && Date.now() >= v.expiresAt) {
            await reqRef.update({ status: "expired" });
        }
        return res.json({ success: true });
    } catch (e) {
        console.error("expire-topup xatoligi:", e);
        return res.status(500).json({ success: false, error: "Server xatoligi" });
    }
});

// ================= 5.3) TELEGRAM WEBHOOK — "kartaga pul tushdi" botidan =================
app.post("/api/telegram-webhook", async (req, res) => {
    try {
        const update = req.body || {};
        const msg = update.message || update.channel_post || update.edited_message;
        if (!msg || !msg.text) return res.status(200).send("ok");

        const text = msg.text;
        const compact = text.replace(/\s/g, "");
        const match = compact.match(/(\d{4,9})(so'?m|som|uzs)/i);
        if (!match) return res.status(200).send("ok");

        const amount = parseInt(match[1], 10);
        const now = Date.now();

        const paymentRef = db.ref("payments").push();
        const paymentData = { amount, rawText: text, receivedAt: now, matched: false };

        const pendingSnap = await db.ref("topupRequests").orderByChild("uniqueAmount").equalTo(amount).once("value");
        let target = null;
        pendingSnap.forEach((child) => {
            const v = child.val();
            if (v.status === "pending" && v.expiresAt > now) target = { key: child.key, ...v };
        });

        if (target) {
            await db.ref(`users/${target.uid}/balance`).transaction((cur) => (cur || 0) + target.baseAmount);
            await db.ref(`topupRequests/${target.key}`).update({ status: "approved", approvedAt: now, matchedBy: "auto" });
            paymentData.matched = true;
            paymentData.matchedRequestId = target.key;
            await paymentRef.set(paymentData);
        } else {
            await paymentRef.set(paymentData);
            await sendTelegramMessage(
                `⚠️ <b>Mos kelmagan to'lov!</b>\nSumma: <b>${amount.toLocaleString("uz-UZ")} so'm</b>\nXabar: ${text}\n\n` +
                    `Iltimos, admin panel → "Mos kelmagan to'lovlar" bo'limida qo'lda biriktiring.`
            );
        }
        return res.status(200).send("ok");
    } catch (e) {
        console.error("telegram-webhook xatoligi:", e);
        return res.status(200).send("ok");
    }
});

// ================= 5.4) BUYURTMA BERISH (Stars / Premium) — balansdan yechish =================
app.post("/api/create-order", async (req, res) => {
    try {
        const { idToken, type, amount, price, label, duration, service_type } = req.body || {};
        if (!idToken) return res.status(401).json({ success: false, error: "Avtorizatsiya talab qilinadi" });
        const decoded = await admin.auth().verifyIdToken(idToken);
        const uid = decoded.uid;

        const priceNum = Math.floor(Number(price));
        if (!priceNum || priceNum <= 0) return res.json({ success: false, error: "Noto'g'ri narx" });

        const balRef = db.ref(`users/${uid}/balance`);
        const result = await balRef.transaction((cur) => {
            const bal = cur || 0;
            if (bal < priceNum) return;
            return bal - priceNum;
        });

        if (!result.committed) {
            return res.json({ success: false, code: "insufficient_balance", error: "Balans yetarli emas" });
        }

        const newOrderRef = db.ref("orders").push();
        await newOrderRef.set({
            uid,
            email: decoded.email || "",
            status: "pending",
            createdAt: Date.now(),
            type: type || null,
            amount: amount || null,
            price: priceNum,
            label: label || "",
            duration: duration || null,
            service_type: service_type || null,
        });

        return res.json({ success: true, orderId: newOrderRef.key });
    } catch (e) {
        console.error("create-order xatoligi:", e);
        return res.status(500).json({ success: false, error: "Server xatoligi" });
    }
});

