app.post("/api/list-topups", async (req, res) => {
    if (!checkAdminSecret(req, res)) return;
    try {
        const snap = await db.ref("topupRequests").orderByChild("status").equalTo("pending").once("value");
        const requests = [];
        snap.forEach((child) => requests.push({ key: child.key, ...child.val() }));
        requests.sort((a, b) => b.createdAt - a.createdAt);
        res.json({ success: true, requests });
    } catch (e) {
        console.error(e);
        res.status(500).json({ success: false, error: "Server xatoligi" });
    }
});

// ================= 5.7) ADMIN: TASDIQLASH / RAD ETISH =================
app.post("/api/approve-topup", async (req, res) => {
    if (!checkAdminSecret(req, res)) return;
    try {
        const { requestId, action } = req.body || {};
        const reqRef = db.ref(`topupRequests/${requestId}`);
        const snap = await reqRef.once("value");
        if (!snap.exists()) return res.json({ success: false, error: "So'rov topilmadi" });
        const v = snap.val();

        if (action === "approve") {
            await db.ref(`users/${v.uid}/balance`).transaction((cur) => (cur || 0) + v.baseAmount);
            await reqRef.update({ status: "approved", approvedAt: Date.now(), matchedBy: "admin" });
        } else if (action === "reject") {
            await reqRef.update({ status: "rejected" });
        } else {
            return res.json({ success: false, error: "Noma'lum amal" });
        }
        res.json({ success: true });
    } catch (e) {
        console.error(e);
        res.status(500).json({ success: false, error: "Server xatoligi" });
    }
});

