// ================= 5.9) ADMIN: QO'LDA BIRIKTIRISH =================
app.post("/api/manual-match", async (req, res) => {
    if (!checkAdminSecret(req, res)) return;
    try {
        const { paymentKey, requestId } = req.body || {};
        const reqSnap = await db.ref(`topupRequests/${requestId}`).once("value");
        if (!reqSnap.exists()) return res.json({ success: false, error: "So'rov topilmadi (ID noto'g'ri)" });
        const v = reqSnap.val();
        if (v.status === "approved") return res.json({ success: false, error: "Bu so'rov allaqachon tasdiqlangan" });

        await db.ref(`users/${v.uid}/balance`).transaction((cur) => (cur || 0) + v.baseAmount);
        await db.ref(`topupRequests/${requestId}`).update({ status: "approved", approvedAt: Date.now(), matchedBy: "admin-manual" });
        if (paymentKey) {
            await db.ref(`payments/${paymentKey}`).update({ matched: true, matchedRequestId: requestId });
        }
        res.json({ success: true });
    } catch (e) {
        console.error(e);
        res.status(500).json({ success: false, error: "Server xatoligi" });
    }
});

