// 6) MUDDATI O'TGAN SO'ROVLARNI FON REJIMIDA AVTOMATIK TOZALASH
//    (bu — HAQIQIY doimiy server bo'lgani uchun, har 15 soniyada o'zi tekshiradi;
//     foydalanuvchi brauzerini yopib ketgan taqdirda ham ishlayveradi)
// ---------------------------------------------------------------------------
async function expireStaleTopups() {
    try {
        const now = Date.now();
        const snap = await db.ref("topupRequests").orderByChild("status").equalTo("pending").once("value");
        const updates = {};
        snap.forEach((child) => {
            const v = child.val();
            if (v.expiresAt <= now) updates[`${child.key}/status`] = "expired";
        });
        if (Object.keys(updates).length > 0) {
            await db.ref("topupRequests").update(updates);
            console.log(`${Object.keys(updates).length} ta so'rov muddati tugagani sababli bekor qilindi.`);
        }
    } catch (e) {
        console.error("expireStaleTopups xatoligi:", e);
    }
}
setInterval(expireStaleTopups, 15 * 1000);

